#include <iostream>
#include <type_traits>
template <typename T, typename U>
struct is_same_type {
  static constexpr bool value = false;
};

template <typename T>
struct is_same_type<T, T> {
  static constexpr bool value = true;
};

int main(){
  static_assert(is_same_type<int,int>::value, "Error");
  static_assert(!is_same_type<int,double>::value, "Error");
  return 0;
}
